import Foundation

struct LibraryWorkout: Identifiable, Hashable {
    let slug: String
    let name: String
    let equipment: String
    let muscle: String
    let routineID: String?

    var id: String { slug }

    var frames: [String] {
        (1...3).map { "library/\(slug)/frame-\($0)" }
    }

    var grade: WashGrade {
        guard let routineID else { return .grayscale }
        return WashGrade.forRoutine(routineID)
    }

    var hints: [String] {
        ExerciseTips.set(for: name).tips
    }

    var hintSource: String? {
        ExerciseTips.set(for: name).source
    }
}

